mapper.insert:
INSERT INTO conversation_summary(
    session_id,content,covered_sequence,covered_turns,version,input_truncated,
    model_name,prompt_tokens,completion_tokens,total_tokens,duration_millis
)
SELECT session.id,CAST(#{content} AS jsonb),#{through},#{coveredTurns},
    #{expectedVersion}+1,#{truncated},#{model},#{usage.promptTokens},
    #{usage.completionTokens},#{usage.totalTokens},#{duration}
FROM chat_session session
WHERE session.id=#{sessionId,typeHandler=com.febridge.persistence.UuidTypeHandler}
    AND session.owner_user_id=#{ownerId,typeHandler=com.febridge.persistence.UuidTypeHandler}
    AND session.active_request=#{requestId,typeHandler=com.febridge.persistence.UuidTypeHandler}
    AND session.locked_until > CURRENT_TIMESTAMP
    AND COALESCE((SELECT version FROM conversation_summary
        WHERE session_id=session.id),0)=#{expectedVersion}
ON CONFLICT(session_id) DO UPDATE SET
    content=EXCLUDED.content,covered_sequence=EXCLUDED.covered_sequence,
    covered_turns=EXCLUDED.covered_turns,version=EXCLUDED.version,
    input_truncated=EXCLUDED.input_truncated,model_name=EXCLUDED.model_name,
    prompt_tokens=EXCLUDED.prompt_tokens,completion_tokens=EXCLUDED.completion_tokens,
    total_tokens=EXCLUDED.total_tokens,duration_millis=EXCLUDED.duration_millis,
    updated_at=CURRENT_TIMESTAMP
WHERE conversation_summary.version=#{expectedVersion}
